  "applicable_norms": [
    {
      "policy_source_id": "q9",
      "interpretation": "Assistant must not perform actions outside the scope of declared policy (technical support, overdue bill payment, line suspension, plan options) without explicit user request or necessity.",
      "modality": "PERMIT"
