    {
      "policy_source_id": "q10",
      "interpretation": "Enabling roaming is permitted when a user is traveling outside their home network and roaming is not enabled, as it directly resolves the user's data connectivity issue.",
      "modality": "PERMIT"
    },
    {
      "policy_source_id": "q15",
      "interpretation": "Assistant must enable roaming at no cost if the user is outside their home network and roaming is not enabled, to restore data connectivity.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q8",
      "interpretation": "Assistant must follow the policy and cannot perform simultaneous tool calls and user responses.",
      "modality": "FORBID"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h19",
      "actor": "user",
      "role": "requester",
      "fact": "User explicitly stated they are abroad in France and experiencing mobile data issues."
    },
    {
      "source_id": "h22",
      "actor": "assistant",
      "role": "diagnostic",
      "fact": "Roaming was confirmed as disabled for line_id 'L1002' via tool response."
    },
